'use strict';
// Presentation only: the existing scripts own selection, data, and Leaflet maps.
window.Dashboard=(()=>{
 const county=document.body.classList.contains('county-page');
 const main=document.querySelector('main');
 const mapCard=document.querySelector(county?'.county-map-card':'.map-shell');
 const status=document.querySelector(county?'.county-result':'.detail');
 const candidates=document.querySelector(county?'#county-candidates':'#bergen-candidates');
 const summary=document.createElement('section');summary.className='area-summary';summary.id='area-summary';summary.tabIndex=-1;summary.setAttribute('aria-label',county?'Fylkesinformasjon':'Kommuneinformasjon');summary.innerHTML='<p>Laster områdeinformasjon …</p>';main.prepend(summary);
 const heading=document.createElement('h2');heading.className='map-heading';heading.textContent=county?'Fylkeskart':'Kommunekart';mapCard.prepend(heading);
 if(!county)heading.after(document.querySelector('#party-filter'));
 const mobile=document.createElement('nav');mobile.className='mobile-tabs';mobile.setAttribute('aria-label','Dashboard');summary.after(mobile);
 const statusHeading=document.createElement('h2');statusHeading.className='status-heading';statusHeading.textContent='Politisk status';status.prepend(statusHeading);
 const statusTabs=document.createElement('div');statusTabs.className='status-tabs';statusHeading.after(statusTabs);
 let view='map',political='poll',panels={},mapInstance;
 const mobileQuery=matchMedia('(max-width:639px)');
 function tabs(host,items,select){host.setAttribute('role','tablist');host.innerHTML=items.map(([key,label])=>`<button type="button" role="tab" data-tab="${key}" id="${host.className}-${key}" aria-selected="false" tabindex="-1">${label}</button>`).join('');host.addEventListener('click',e=>{const b=e.target.closest('button');if(b)select(b.dataset.tab)});host.addEventListener('keydown',e=>{const buttons=[...host.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(i<0)return;let n;if(e.key==='ArrowRight')n=(i+1)%buttons.length;if(e.key==='ArrowLeft')n=(i+buttons.length-1)%buttons.length;if(e.key==='Home')n=0;if(e.key==='End')n=buttons.length-1;if(n!=null){e.preventDefault();buttons[n].focus();select(buttons[n].dataset.tab)}})}
 tabs(mobile,[['map','Kart'],['poll','Måling'],['election','2023'],['candidates','Kandidater']],key=>{view=key;if(key==='poll'||key==='election')political=key;apply()});
 tabs(statusTabs,[['poll','Meningsmåling'],['election','Valgresultat 2023'],['change','Endring']],key=>{political=key;if(mobileQuery.matches)view=key==='election'?'election':'poll';apply()});
 function mark(host,key){host.querySelectorAll('button').forEach(b=>{const active=b.dataset.tab===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;const p=host===mobile?({map:mapCard,poll:status,election:status,candidates}[b.dataset.tab]):panels[b.dataset.tab];if(p){if(!p.id)p.id=`dashboard-${b.dataset.tab}`;b.setAttribute('aria-controls',p.id)}})}
 function apply(){const small=mobileQuery.matches;mapCard.hidden=small&&view!=='map';status.hidden=small&&!['poll','election'].includes(view);candidates.hidden=small&&view!=='candidates';Object.entries(panels).forEach(([key,p])=>{p.hidden=key!==political;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',`status-tabs-${key}`)});mark(mobile,view);mark(statusTabs,political);requestAnimationFrame(()=>mapInstance?.invalidateSize({pan:false}))}
 mobileQuery.addEventListener('change',apply);
 const candidateHeading=candidates.querySelector('.candidate-heading,.county-section-heading');const toggle=document.createElement('button');toggle.type='button';toggle.className='candidate-toggle';toggle.textContent='Se alle kandidater ↗';toggle.setAttribute('aria-expanded','false');candidateHeading.append(toggle);toggle.addEventListener('click',()=>{const grid=candidates.querySelector('.candidate-grid,.county-candidate-grid'),expanded=grid.classList.toggle('is-expanded');toggle.textContent=expanded?'Vis kandidatstripe':'Se alle kandidater ↗';toggle.setAttribute('aria-expanded',String(expanded))});
 function candidateLabels(){candidates.querySelectorAll('.candidate-card,.county-candidate').forEach(card=>{if(card.querySelector('.mobile-party-name'))return;const party=card.querySelector('.candidate-party,.county-candidate-party span')?.textContent;if(party){const span=document.createElement('span');span.className='mobile-party-name';span.textContent=party;(card.querySelector('.candidate-copy')||card.querySelector('h3')).append(span)}})}
 function meta(total,isCounty,population,areaCode){const count=population?.[isCounty?'counties':'municipalities']?.[areaCode];const date=population?.asOf?new Date(population.asOf+'T12:00:00').toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric'}):'';return `<p class="area-meta">${Number.isInteger(count)?`<a class="population" href="${population.source}" target="_blank" rel="noopener" title="${population.sourceLabel} · per ${date}" aria-label="${count.toLocaleString('nb-NO')} innbyggere per ${date}. Kilde: ${population.sourceLabel}">${count.toLocaleString('nb-NO')} innbyggere</a>`:''}${total!=null?`<span>${total} ${isCounty?'fylkestingsplasser':'kommunestyreplasser'}</span>`:''}<a href="https://www.valg.no/en/news/latest-news/valgdagen-blir-13.-september-2027" target="_blank" rel="noopener">Valgdag 13. september 2027</a></p>`}
 function electionBaseline(election,metadata){return Object.fromEntries((election?.results||[]).map(row=>[Object.keys(metadata).find(key=>metadata[key].name===row.party)||row.party,row.percent]))}
 function changePanel(poll,previous,metadata){const panel=document.createElement('section');panel.className='change-panel';if(!poll){panel.innerHTML='<div class="empty"><h3>Ingen måling å sammenligne</h3><p>Endring vises når en meningsmåling er registrert for valgt område.</p></div>';return panel}const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>n.toLocaleString('nb-NO',{minimumFractionDigits:1,maximumFractionDigits:1});const rows=Object.entries(poll.values).map(([key,value])=>{const before=previous[key],delta=before==null||key==='Andre'?null:Math.round((value-before)*10)/10,sign=delta>0?'↑ +':delta<0?'↓ −':'',label=metadata[key]?.name||key;return `<div class="bar-row"><span class="bar-label" title="${escape(label)}">${escape(({H:'Høyre',V:'Venstre',R:'Rødt'})[key]||key)}</span><div class="bar-track"><div class="bar-fill" style="--party:${metadata[key]?.color||'#8993a3'};--value:${value/Math.max(...Object.values(poll.values))*100}%"></div></div><span class="bar-value">${fmt(value)}</span><span class="bar-previous">${before==null?'–':fmt(before)}</span><span class="bar-change ${delta>0?'change-up':delta<0?'change-down':''}">${delta==null?'–':sign+fmt(Math.abs(delta))}</span></div>`}).join('');panel.innerHTML='<div class="poll-head"><h3>Endring fra valgresultat 2023</h3></div><div class="chart change-chart" role="group" aria-label="Endring i prosentpoeng siden valgresultatet i 2023"><div class="poll-table-head"><span>Parti</span><span></span><span>Nå</span><span>2023</span><span>Endring</span></div>'+rows+'</div><div class="poll-total"><span>Endring i prosentpoeng</span><strong>2023 → nå</strong></div><p class="poll-meta">«–» betyr at et separat sammenlignbart resultat mangler i datagrunnlaget. «Andre» kan omfatte ulike lister og sammenlignes derfor ikke.</p>';return panel}
 function municipal(m,e,p,metadata,population){const content=document.querySelector('#detail-content'),info=content.querySelector('.municipality-summary');summary.replaceChildren();const name=info.querySelector('h2'),block=document.createElement('div');block.className='area-heading';block.append(name);block.insertAdjacentHTML('beforeend',meta(e?.totalSeats,false,population,m.id));summary.append(block,...info.querySelectorAll('.mayor,.mayor-note'));info.remove();heading.textContent=`Kommunekart · ${m.name}`;const grid=content.querySelector('.detail-data-grid');panels={poll:grid.querySelector('.poll-panel'),election:grid.querySelector('.election-2023'),change:changePanel(p,electionBaseline(e,metadata),metadata)};if(!panels.election){panels.election=document.createElement('section');panels.election.innerHTML='<p>Valgresultatet kunne ikke lastes.</p>';grid.append(panels.election)}grid.append(panels.change);if(!candidates.querySelector('.candidate-card')){candidates.hidden=false;candidates.querySelector('#candidate-grid').innerHTML='<p class="candidate-empty">Ingen kandidatopplysninger registrert for denne kommunen ennå.</p>'}candidateLabels();apply()}
 function updateCounty(c,e,p,metadata,population){const info=document.querySelector('#county-detail-card');summary.replaceChildren(info);const name=info.querySelector('h2');const block=document.createElement('div');block.className='area-heading';name.before(block);block.append(name);block.insertAdjacentHTML('beforeend',meta(e?.totalSeats,true,population,c.code));heading.textContent=`Fylkeskart · ${c.name}`;const grid=document.querySelector('.county-data-grid');grid.querySelector('.change-panel')?.remove();panels={poll:document.querySelector('#county-poll-column'),election:document.querySelector('#county-result-column'),change:changePanel(p,Object.fromEntries(Object.entries(e?.rows||{}).map(([k,r])=>[k,r.value])),metadata)};grid.append(panels.change);candidateLabels();apply()}
 return {municipal,updateCounty,electionBaseline,setMap(map){mapInstance=map;new ResizeObserver(()=>map.invalidateSize({pan:false})).observe(mapCard)},apply};
})();
